/**
 * Country → currency → time zone reference data (PRD §8.1, §16.1).
 * Generated by scripts/generate-countries.py from IANA tzdata + Unicode CLDR.
 * Plain text names only — never flags, maps or emblems.
 */
import data from '../data/countries.json';

export type LanguageCode = 'en' | 'ar' | 'ur' | 'hi';

export interface Country {
  code: string; // ISO 3166-1 alpha-2
  names: Record<LanguageCode, string>;
  currency: string; // ISO 4217
  decimals: number; // ISO 4217 minor units
  timeZones: string[]; // IANA
}

export const COUNTRIES: Country[] = data as Country[];

const byCode = new Map(COUNTRIES.map((c) => [c.code, c]));

export function getCountry(code: string): Country | undefined {
  return byCode.get(code);
}

/** Countries sorted alphabetically in the given language. */
export function countriesSorted(lang: LanguageCode): Country[] {
  const collator = new Intl.Collator(lang);
  return [...COUNTRIES].sort((a, b) => collator.compare(a.names[lang], b.names[lang]));
}

/** Default zone when a country has exactly one; otherwise the Admin must choose. */
export function defaultTimeZone(country: Country): string | null {
  return country.timeZones.length === 1 ? country.timeZones[0] : null;
}
